INSERT INTO `brands` (`id`, `name`, `description`, `logo`, `banner`, `created_at`) VALUES
(1, 'La Roche-Posay', 'La Roche-Posay — эксперт в области исследований микробиома кожи. Знания вдохновляют бренд на создание инновационных косметических средств с доказанной эффективностью.\r\n\r\nБренд сотрудничает с дерматологами на всех этапах, начиная с разработки. Создаются средства с эффективной концентрацией активных ингредиентов, которые подходят даже для чувствительной кожи.', '/apteka/uploads/brands/1764764771_69302c63f0a4c.jpg', '/apteka/uploads/brands/banner_1777459120_69f1dfb039b39.webp', '2025-12-03 15:00:12'),
(2, 'Эвалар', '«Эвалар» — фармацевтическое предприятие, крупнейший российский производитель биологически активных добавок. Компания создана в 1991 году на базе ФНПЦ «Алтай». \r\nОсновная продукция — биологически активные добавки различных форм выпуска на природном сырье растительного, минерального и животного происхождения.', '/apteka/uploads/brands/1766087585_69445ba1be405.png', NULL, '2025-12-18 22:53:05'),
(3, 'SOLGAR', 'Бренд Solgar является синонимом высококачественных пищевых добавок, которым на протяжении многих лет доверяют потребители во всем мире. Предлагая богатый ассортимент продуктов, ориентированных на здоровье и благополучие, Solgar выделяется своим вниманием к деталям и уникальными рецептами. Используя тщательно отобранные ингредиенты, эти добавки являются ответом на потребности современного образа жизни, который часто требует поддержки в ежедневном рационе.\r\n\r\nSolgar сочетает в себе традиции и современность, что делает продукты не только эффективными, но и совместимыми с последними тенденциями в добавках. Компания делает ставку на качество и инновации, предлагая широкий спектр активных ингредиентов, таких как витамины, минералы, аминокислоты и растительные экстракты. Многие из этих продуктов предназначены для людей с различными диетическими требованиями, включая вегетарианцев и веганов. Добавки Solgar разработаны для обеспечения организма необходимыми питательными веществами, что имеет решающее значение для поддержания здоровья и хорошего физического и психического состояния.', '/apteka/uploads/brands/1777372621_69f08dcd828ff.png', '/apteka/uploads/brands/banner_1777459311_69f1e06f8443a.webp', '2026-04-28 13:37:01'),
(4, 'NOVARTIS', 'На протяжении более чем 250 лет – и 30 лет как Novartis – мы добиваемся научных прорывов с одной целью: для людей. Сегодня мы решаем самые сложные задачи в области здравоохранения и воплощаем инновации в лекарствах, которые определяют будущее пациентов.', '/apteka/uploads/brands/1777461281_69f1e82157bb3.png', '/apteka/uploads/brands/banner_1777461281_69f1e82157d23.png', '2026-04-29 14:14:41');

