INSERT INTO `products` (`id`, `category_id`, `name`, `short_description`, `description`, `long_description`, `price`, `supplier`, `brand_id`, `brand`, `prescription`, `usage_info`, `stock`, `image`, `photo`, `created_at`, `label`, `indications`, `composition`, `contraindications`, `drug_interactions`, `overdose`) VALUES
(1, NULL, 'АВК Олл Витамин комплекс Коэнзим Q10 100мг капсулы №30', 'Лекарственный бад Коэнзим на основе экстракта биомолекул Psh02-1 L-Argesin', 'О продукте\r\nКоэнзим Q10 - это биологически активная добавка к пище, необходимая для осуществления метаболических реакций в клетках организма. Капсулы с коэнзимом Q10 являются отличным способом компенсировать недостаток коэнзима в организме и поддерживать свой иммунитет, энергию и красоту.\r\n\r\nОсновная функция коэнзима Q10 - участие в процессе выработки клеточной энергии, запасаемой организмом в митохондриях клеток в виде АТФ (Аденозинтрифосфата). Помимо этого Коэнзим Q10 является мощным антиоксидантом, замедляющим свободно-радикальные процессы\r\n\r\nКоэнзим Q10 способствует:\r\n\r\nобразованию энергии для работы головного мозга, сердца, печени, нервной и мышечной систем;\r\nантиоксидантной защите организма и защите от свободных радикалов, в т.ч. уменьшению гипоксических повреждений (повреждение ткани, вызванное недостатком кислорода);\r\nподдержанию функционального состояния органов сердечно-сосудистой системы;\r\nснижению риска развития сердечно-сосудистых заболеваний\r\nнормализации повышенного артериального давления\r\nукреплению иммунной системы;\r\nсохранении красоты и молодости, замедлению процессов старения организма\r\n\r\nИсточник: https://apteka-april.ru/product/343607-avk_oll_vitamin_kompleks_koenzim_q10_100mg_kapsuly_30', '', 633.00, 'ООО \"НУТРИЛЕНТ\"', NULL, 'NEW', 0, 'Рекомендуется в качестве биологически активной добавки к пище – дополнительного источника Коэнзима Q10.\r\n\r\nИсточник: https://apteka-april.ru/product/343607-avk_oll_vitamin_kompleks_koenzim_q10_100mg_kapsuly_30', 244, 'https://pictures.apteka-april.ru/products/343607/800/3ea6d566-8e6b-4c97-ac47-d5f7adb9c499.webp', NULL, '2025-11-24 12:25:47', 'bad', '', '', '', '', ''),
(2, NULL, 'Омега 3-6-9 Актив капсулы №60', 'Омега 3-6-9 в капсулах является идеальным решением для поддержания здоровья сердца и сосудов.', 'Омега 3-6-9 в капсулах является идеальным решением для поддержания здоровья сердца и сосудов.', 'Каждая капсула массой 1600 мг содержит натуральный морской рыбий жир, который богат полезными жирными кислотами Omega-3, Omega-6 и Omega-9.\r\nРегулярный прием этих капсул улучшает обмен веществ, позволяет укрепить иммунную систему, повысить тонус организма и снизить уровень холестерина в крови.\r\nКроме того, Omega-3-6-9 устраняет симптомы депрессии и уменьшает риск развития болезней сердца и сосудов.', 630.00, 'ООО \"НУТРИЛЕНТ\"', NULL, NULL, 0, 'Индивидуальная непереносимость компонентов БАД.\r\nПеред применением рекомендуется проконсультироваться с врачом.\r\nПеред применением БАД детьми необходимо проконсультироваться с врачом-педиатром.\r\n\r\nРекомендуется в качестве БАД к пище – дополнительного источника полиненасыщенных жирных кислот (ПНЖК) Омега-3 (в том числе докозагексаеновой кислоты, эйкозапентаеновой кислоты, альфа-линоленовой кислоты), ПНЖК Омега-6 (в том числе линолевой кислоты).\r\n\r\nВзрослым и детям старше 14 лет по 1 капсуле 3 раза в день во время еды.\r\nПродолжительность приема: 1 месяц. При необходимости прием можно повторить.', 331, 'https://uteka.ru/media/1024/9/0a/90a18cdbed9b6372163b576bab41c952.jpg', NULL, '2025-11-29 17:48:55', 'bad', 'Рекомендуется в качестве БАД к пище – дополнительного источника полиненасыщенных жирных кислот (ПНЖК) Омега-3 (в том числе докозагексаеновой кислоты, эйкозапентаеновой кислоты, альфа-линоленовой кислоты), ПНЖК Омега-6 (в том числе линолевой кислоты).', 'Соевое масло, оболочка (желатин, глицерин – загуститель, вода), рыбий жир, оливковое масло, льняное масло. На предприятии используется сырье, содержащее продукты переработки молока, рыбы, ракообразных и сои.\r\n\r\nСодержание в суточной дозировке (3 капсулы):\r\nПНЖК Омега-3 488 мг\r\nЭйкозапентаеновая кислота 180 мг\r\nДокозагексаеновая кислота 120 мг\r\nАльфа-линоленовая кислота 120 мг\r\n\r\nПНЖК Омега-6 1078,5 мг\r\nЛиноленовая кислота 1059 мг\r\n\r\nПНЖК Омега-9 730 мг\r\nОлеиновая кислота 621 мг', 'Индивидуальная непереносимость компонентов БАД.\r\nПеред применением рекомендуется проконсультироваться с врачом.\r\nПеред применением БАД детьми необходимо проконсультироваться с врачом-педиатром.', 'усиливает фармакологические эффекты антикоагулянтов и антиагрегантов;\r\nповышает активность гиполипидемических препаратов (фибратов и статинов), устраняет их побочные эффекты;\r\nспособствует всасыванию добавок с жирорастворимыми витаминами.', 'Передозировка биологически активной добавкой (БАД) «Омега 3-6-9» возможна, при избытке омега-кислот появляются мышечные спазмы, боли в костях и суставах, нарушается выделительная функция почек.'),
(3, NULL, 'Акнекутан', 'Лекарственный препарат разработанный для лечения угревой болезни и профилактике проблемная кожа', 'Акнекутан® (Acnecutan)\r\nОписание лекарственной формы\r\nКапсулы, 8 мг: твердые, желатиновые, размер №3, коричневого цвета.\r\nКапсулы, 16 мг: твердые, желатиновые, размер №1, корпус белого цвета, крышечка — зеленого.\r\nСодержимое капсул — воскообразная паста желто-оранжевого цвета.', 'Действующее вещество\r\nИзотретиноин* (Isotretinoin*)\r\nATX\r\nD10BA01 Изотретиноин\r\nФармакологическая группа\r\nСредство лечения угревой сыпи [Дерматотропные средства]\r\nНозологическая классификация (МКБ-10)\r\nСписок кодов МКБ-10\r\nL70 Угри\r\n\r\nФармакодинамика\r\nИзотретиноин — стереоизомер полностью транс-ретиноевой кислоты (третиноина).\r\nТочный механизм действия изотретиноина еще не выявлен, однако установлено, что улучшение клинической картины тяжелых форм акне связано с подавлением активности сальных желез и гистологически подтвержденным уменьшением их размеров. Кожное сало — основной субстрат для роста Propionibacterium acnes, поэтому уменьшение образования кожного сала подавляет бактериальную колонизацию протока.\r\nАкнекутан® подавляет пролиферацию себоцитов и действует на акне, восстанавливая нормальный процесс дифференцировки клеток, стимулирует регенерационные процессы.\r\n\r\nКроме того, доказано противовоспалительное действие изотретиноина на кожу.\r\n\r\nФармакокинетика\r\nПоскольку кинетика изотретиноина и его метаболитов носит линейный характер, его концентрацию в плазме в ходе терапии можно предсказать на основании данных, полученных после однократного приема. Это свойство препарата также говорит о том, что он не влияет на активность микросомальных ферментов печени, участвующих в метаболизме ЛС.\r\nВысокая биодоступность препарата Акнекутан® обусловлена большой долей растворенного изотретиноина в препарате и может увеличиваться при условии приема препарата с пищей.\r\nУ больных с акне после приема 80 мг изотретиноина натощак Cmax в плазме в равновесном состоянии составляла 310 нг/мл (диапазон 188–473 нг/мл), Tmax — 2–4 ч. Концентрация изотретиноина в плазме в 1,7 раза выше, чем в крови, вследствие плохого проникновения изотретиноина в эритроциты. Связь с белками плазмы (преимущественно с альбумином) — 99,9%.\r\n\r\nCss изотретиноина в крови у больных с тяжелыми формами акне, принимавших по 40 мг препарата 2 раза в сутки, колебались от 120 до 200 нг/мл. Концентрации 4-оксо-изотретиноина (основной метаболит) у этих больных в 2,5 раза превышали концентрации изотретиноина.\r\n\r\nКонцентрация изотретиноина в эпидермисе в 2 разе ниже, чем в сыворотке.\r\n\r\nМетаболизируется с образованием 3 основных биологически активных метаболитов — 4-оксо-изотретиноина (главный), третиноина (полностью транс-ретиноевая кислота) и 4-оксо-ретиноина, а также менее значимых метаболитов, включающих также глюкурониды. Поскольку in vivo изотретиноин и третиноин обратимо превращаются друг в друга, метаболизм третиноина связан с метаболизмом изотретиноина. 20–30% дозы изотретиноина метаболизируется путем изомеризации. В фармакокинетике изотретиноина у человека существенную роль может играть кишечно-печеночная рециркуляция.\r\n\r\nИсследования in vitro показали, что в превращении изотретиноина в 4-оксо-изотретиноин и третиноин участвуют несколько изоферментов цитохрома P450, при этом ни одна из изоформ, по всей видимости, не играет доминирующей роли. Изотретиноин и его метаболиты не оказывают существенного влияния на активность изоферментов цитохрома P450.\r\nT1/2 терминальной фазы для изотретиноина — в среднем 19 ч; для 4-оксо-изотретиноина — в среднем 29 ч.\r\nИзотретиноин выводится почками и с желчью примерно в равных количествах.\r\nОтносится к природным (физиологическим) ретиноидам. Эндогенные концентрации ретиноидов восстанавливаются примерно через 2 нед после окончания приема препарата.', 3192.00, 'СМБ Технолоджи С.А.', NULL, NULL, 1, 'Противопоказания\r\nповышенная чувствительность к препарату или его компонентам;\r\nпеченочная недостаточность;\r\nгипервитаминоз А;\r\nвыраженная гиперлипидемия;\r\nсопутствующая терапия тетрациклинами;\r\nбеременность, установленная и планируемая (возможно тератогенное и эмбриотоксическое действие);\r\nпериод кормления грудью;\r\nдетский возраст до 12 лет.', 23, 'https://pictures.apteka-april.ru/products/104640/390/5e218f88-24e4-401d-8cab-ba4904899302.webp', NULL, '2025-12-01 12:17:15', 'strong', NULL, NULL, NULL, NULL, NULL),
(4, NULL, 'Нурофен таблетки 200мг №10', 'Противовоспалительное средство, которое оказывает обезболивающее, жаропонижающее и противовоспалительное действие', 'Во время длительного лечения необходим контроль картины периферической крови и функционального состояния печени и почек. При появлении симптомов гастропатии показан тщательный контроль, включающий проведение\r\nэзофагогастродуоденоскопии, общий анализ крови (определение гемоглобина), анализ кала на скрытую кровь. При необходимости определения 17-кетостероидов препарат следует отменить за 48 часов до исследования. Больные должны воздерживаться от всех видов деятельности, связанных с управлением транспортными средствами и работой с движущимися механизмами, а также от других видов потенциально опасных видов деятельности, связанных с концентрацией внимания и повышенной скоростью психомоторных реакций.\r\nВ период лечения следует воздержаться от употребления спиртных напитков.\r\n\r\nВлияние на способность управлять транспортным средством и механизмами\r\nБольные должны воздерживаться от всех видов деятельности, связанных с управлением транспортными средствами и работой с движущимися механизмами, а также от других видов потенциально опасных видов деятельности, связанных с концентрацией внимания и повышенной скоростью психомоторных реакций.', '', 209.00, 'Reckitt Benckiser Healthcare Manufacturing/ Реккитт Бенкизер Хелскэр Мануфэкчуринг', NULL, NULL, 0, 'Нурофен® назначают взрослым и детям старше 12 лет внутрь, после еды в таблетках по 200 мг 3-4 раза в сутки. Таблетки следует запивать водой.\r\nДля достижения быстрого терапевтического эффекта у взрослых доза может быть увеличена до 400 мг (2 таблетки) 3 раза в сутки.\r\nДетям от 6 до 12 лет: по 1 таблетке не более 4 раз в день; препарат может использоваться только в случае массы тела ребенка более 20 кг. Интервал между приемом таблеток не менее 6 часов. Не принимать больше 6 таблеток за 24 часа. Максимальная суточная доза составляет 1200 мг. Если при приеме препарата в течение 2-3 дней симптомы сохраняются, необходимо прекратить лечение и обратиться к врачу.', 4459, 'https://pictures.apteka-april.ru/products/207618/390/77c110867842e12fc00fe25b63603365.webp', NULL, '2025-12-02 15:20:52', '', 'Нурофен применяют при головной боли, мигрени, зубной боли, болезненных менструациях, невралгии, боли в спине, мышечной боли, ревматической боли и боли в суставах; а также при лихорадочном состоянии при гриппе и простудных заболеваниях.', 'Одна таблетка, покрытая оболочкой, содержит активное вещество: 200 мг ибупрофена; вспомогательные вещества: кроскармеллозу натрия 30 мг, натрия лаурилсульфат 0,5 мг, натрия цитрата дигидрат 43,5 мг, стеариновую кислоту 2,0 мг, кремния диоксид коллоидный 1,0 мг. Состав оболочки: кармеллоза натрия 0,7 мг, тальк 33,0 мг, акации камедь 0,6 мг, сахароза 116,1 мг, титана диоксид 1,4 мг, макрогол 6000 0,2 мг, чернила черные [Опакод S-1-277001] (шеллак 28,225 %, краситель железа оксид черный (Е172) 24,65 %, пропиленгликоль 1,3 %, изопропанол* 0,55 %, бутанол* 9,75 %, этанол* 32,275 %, вода очищенная* 3,25 %).\r\n*Растворители, испарившиеся после процесса печати.', 'Эрозивно-язвенные поражения желудочно-кишечного тракта в фазе обострения, в том числе язвенная болезнь желудка и 12-перстной кишки в стадии обострения, язвенный колит, пептическая язва, болезнь Крона;\r\nсердечная недостаточность;\r\nтяжелое течение артериальной гипертензии;\r\nповышенная чувствительность к ибупрофену или к компонентам препарата;\r\nполный или неполный синдром непереносимости ацетилсалициловой кислоты (риносинусит, крапивница, полипы слизистой оболочки носа, бронхиальная астма);\r\nзаболевания зрительного нерва; нарушение цветового зрения, амблиопия, скотома;\r\nдефицит глюкозо-б-фосфатдегидрогеназы, гемофилия и другие нарушения свертываемости крови, гемморагические диатезы, состояния гипокоагуляции\r\nбеременность III триместр, период лактации;\r\nвыраженные нарушения функции печени;\r\nвыраженная почечная недостаточность (клиренс креатинина менее 30 мл/мин);\r\nснижение слуха, патология вестибулярного аппарата;\r\nпериод после проведения аортокоронарного шунтирования;\r\nжелудочно-кишечные кровотечения и внутричерепные кровоизлияния;\r\nгемофилия и другие нарушения свертываемости крови, геморрагические диатезы;\r\nдети до 6 лет.', 'Не рекомендуется одновременный прием таблеток НУРОФЕНа с ацетилсалициловой кислотой (АСК) и другими НПВП. При одновременном назначении ибупрофен снижает противовоспалительное и антиагрегантное действие ацетилсалициловой кислоты (АСК) (возможно повышение частоты развития острой коронарной недостаточности у больных, получающих в качестве антиагрегантного средства малые дозы ацетилсалициловой кислоты (АСК), после начала приема ибупрофена). При назначении с антикоагулянтными и тромболитическими лекарственными средствами (алтеплазой, стрептокиназой, урокиназой) одновременно повышается риск развития кровотечений. Цефамандол, цефаперазон, цефотетан, вальпроевая кислота, пликамицин, увеличивают чистоту развития гипопротромбинемии. Циклоспорин и препараты золота усиливают влияние ибупрофена на синтез простогландинов в почках, что проявляется повышением нефротоксичности. Ибупрофен повышает плазменную концентрацию циклоспорина и вероятность развития его гепатотоксических эффектов. Лекарственные средства, блокирующие канальцевую секрецию, снижают выведение и повышают плазменную концентрацию ибупрофена. Индукторы микросомального окисления (фенитоин, этанол, барбитураты, рифампицин, фенилбутазон, трициклические антидепрессанты) увеличивают продукцию гидроксилированных активных метаболитов, повышая риск развития тяжелых гепатотоксических реакций. Ингибиторы микросомального окисления - снижают риск гепатотоксического действия. Снижает гипотензивную активность вазодилататоров, натрийуретическую у фуросемида и гидрохлортиазида. Снижает эффективность урикозурических препаратов, усиливает действие непрямых антикоагулянтов, антиагрегантов, фибринолитиков. Усиливает побочные эффекты минерапокортикостероидов, глюкокортикостероидов, эстрогенов, этанола. Усиливает эффект пероральных гипогликемических лекарственных средств, производных сульфонилмочевины и инсулина,. Антациды и колестирамин снижают абсорбцию. Увеличивает концентрацию в крови дигоксина, препаратов лития, метотрексата. Кофеин усиливает анальгезирующий эффект.', 'Симптомы: боли в животе, тошнота, рвота, заторможенность, сонливость, депрессия, головная боль, шум в ушах, метаболический ацидоз, кома, острая почечная и печеночная недостаточность, желудочно-кишечные кровотечения, снижение артериального давления (АД), брадикардия, тахикардия, фибрилляция предсердий, остановка дыхания, увеличение протромбинового времени, редко возможны судороги.\r\n\r\nЛечение: промывание желудка (только в течение часа после приема), активированный уголь, щелочное питье, форсированный диурез, симптоматическая терапия. В случае частых или продолжительных судорог, необходимо применять противосудорожные препараты (диазепам или лоразепам внутривенно).'),
(6, NULL, 'La Roche-Posay LIPIKAR LAIT UREA 10%', 'La Roche-Posay Lipikar Lait Urea 10% Увлажняющее молочко для тела тройного действия.', 'La Roche-Posay Lipikar Lait Urea 10% Увлажняющее молочко для тела тройного действия. Увлажняет и смягчает огрубевшую кожу, помогает уменьшить шероховатость, шелушение и стянутость кожи. Имеет нелипкую и нежирную текстуру.\r\nТолько для наружного применения.', 'Лосьон создан для поддержания оптимального уровня увлажнения сухой и чувствительной кожи. Формула с содержанием 10% мочевины способствует мягкому выравниванию текстуры, помогает уменьшить выраженность сухости и обеспечивает ощущение гладкости. Лёгкая текстура распределяется равномерно, быстро впитывается и не оставляет жирного блеска. Подходит для ежедневного применения как самостоятельное средство или в составе комплексного ухода. Может использоваться в течение длительного времени для поддержания комфорта кожного барьера. Универсален, подходит для большинства типов сухой кожи, включая чувствительную.', 2499.00, '', 1, NULL, 0, 'Лосьон наносится на предварительно очищенную и тщательно высушенную кожу. Распределяется мягкими массажными движениями, уделяя внимание зонам с повышенной сухостью. Оптимальная частота применения — 1–2 раза в сутки, утром и вечером, либо по мере необходимости в течение дня. Подходит для регулярного и длительного использования в рамках повседневного ухода. При применении совместно с другими дерматокосметическими средствами рекомендуется выдерживать небольшой интервал для полноценного впитывания.', 34, '/AptekaWebSite/uploads/1777371697_lrp_lipikarlait_urea10__packshot_va_dmi_square1200x1200_na_no-cta_v1.png', NULL, '2025-12-03 12:27:53', '', 'Используется как средство ежедневного ухода за сухой, огрубевшей и чувствительной кожей, нуждающейся в дополнительном увлажнении и восстановлении комфорта. Подходит при периодической стянутости, ощущении шероховатости, сезонной сухости в холодное время года, а также после воздействия факторов, нарушающих естественный барьер кожи (ветер, жёсткая вода, температурные перепады). Может применяться для поддержания мягкости кожи у взрослых и подростков, а также как вспомогательный элемент базового ухода при склонности к сухости отдельных участков тела.', 'Aqua (Water), Urea, Glycerin, Butyrospermum Parkii (Shea) Butter, Brassica Campestris (Rapeseed) Seed Oil, Dicaprylyl Carbonate, Isopropyl Palmitate, Pentylene Glycol, Glycine, Cetearyl Alcohol, Silica, Stearic Acid, Allantoin, Sorbitan Oleate, Sorbitan Tristearate, Glyceryl Stearate, PEG-100 Stearate, PEG-20 Methyl Glucose Sesquistearate, Isohexadecane, Sodium Hydroxide, Sodium Lactate, Myristic Acid, Palmitic Acid, Mannose, Hydroxyacetophenone, Hydroxyethylpiperazine Ethane Sulfonic Acid, Caprylyl Glycol, Citric Acid, Trisodium Ethylenediamine Disuccinate, Xanthan Gum, Polysorbate 80, Acrylamide/Sodium Acryloyldimethyltaurate Copolymer, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Tocopherol, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate, Chlorhexidine Digluconate.', 'Не применяется при индивидуальной непереносимости компонентов формулы. Следует избегать использования на участках с выраженными повреждениями кожи, активным раздражением или нарушением целостности покровов. В случае появления неприятных ощущений применение следует временно прекратить и наблюдать за реакцией кожи.', 'Совместим с большинством нейтральных увлажняющих и успокаивающих средств базового ухода. При использовании совместно с продуктами, содержащими выраженные активы (кислоты, ретиноиды, интенсивные эксфолианты), рекомендуется чередование или разделение по времени, чтобы сохранить комфорт кожи. Не препятствует нанесению макияжа или других поверхностных средств ухода.', 'Случаи передозировки не описаны. При избыточном количестве нанесённого средства возможно ощущение плёнки или липкости, которое проходит после полного впитывания. Никаких системных реакций при наружном применении не ожидается.'),
(7, NULL, 'La Roche-Posay Cicaplast Levres', 'Восстанавливающий бальзам-барьер для губ Cicaplast Levres от La Roche-Posay обеспечивает мгновенное успокаивающее и заживляющее действие. Восстанавливает сухие, потрескавшиеся губы, дарит максимальный комфорт и не оставляет следов.', '', 'Средство предназначено для смягчения и восстановления ощущения комфорта сухих и чувствительных губ. Лёгкая текстура образует на поверхности нежный защитный слой, который помогает удерживать влагу, уменьшает проявления сухости и способствует более гладкому состоянию кожи губ. Подходит для постоянного использования в течение дня, легко наносится, не оставляет липкости и комфортно ощущается при регулярном применении. Универсально и подходит большинству пользователей, которые хотят поддерживать губы мягкими и увлажнёнными, особенно в условиях агрессивных внешних факторов.', 989.00, 'ООО \"НУТРИЛЕНТ\"', 1, NULL, 0, 'Наносится на чистые, сухие губы лёгким распределяющим движением. Можно использовать несколько раз в день по мере необходимости, включая утренний и вечерний уход. Подходит для регулярного, длительного применения и совместим с использованием декоративных средств для губ. При сочетании с другими средствами ухода рекомендуется наносить в последнюю очередь, чтобы создать комфортное защитное покрытие.', 39, 'https://avatars.mds.yandex.net/get-goods_pic/9756927/hat3514c2f20350527120f55baeeec48dc5/600x600', NULL, '2025-12-04 17:22:15', '', 'Рекомендуется для ухода за сухой, раздражённой и склонной к дискомфорту кожей губ. Подходит при ощущении стянутости, шелушения, влиянии холодного воздуха, ветра, пересушенного помещения или после применения средств, способных нарушать естественный защитный слой губ. Может использоваться при эпизодической чувствительности, сезонных изменениях и общем снижении уровня увлажнённости кожи губ.', 'Aqua/water, Ppg-5 Pentaerythrityl Ether, Peg-5 Pentaerythrityl Ether, Butyrospermum Parkii Butter/shea Butter, Cera Alba/beeswax, Panthenol, Hydrogenated Vegetable Oil, Ethylhexyl Palmitate, Silica Silylate, Polybutene, Glycine Soja/soybean Sterols, Aqua/water, Sodium Saccharin, Myristyl Malate Phosphonic Acid, Pentaerythrityl Tetra-di-t-butyl Hydroxyhydrocinnamate.\r\n\r\nФормула включает комплекс увлажняющих и смягчающих компонентов, направленных на поддержание комфортного состояния кожи губ. В основе — вещества, способствующие созданию защитного покрытия и уменьшению ощущения сухости. Дополнительно включены элементы, отвечающие за текстуру, стабильность и равномерное распределение средства.\r\n\r\nСреди функциональных ингредиентов присутствуют компоненты, которые помогают удерживать влагу, обеспечивают мягкость и предотвращают ощущение стянутости. Также включены вспомогательные вещества, формирующие оптимальную консистенцию, улучшающие нанесение и обеспечивающие длительное ощущение комфорта.\r\nКомпозиция подобрана таким образом, чтобы средство было подходящим для регулярного применения и сочеталось с другими продуктами базового ухода.', 'Индивидуальная чувствительность к компонентам состава. Не применять при выраженном воспалении, открытых повреждениях или активных раздражениях кожи губ. При появлении неприятных ощущений следует временно прекратить использование и наблюдать за реакцией.', 'Может сочетаться с большинством уходовых и декоративных продуктов. Не препятствует нанесению бальзамов, увлажняющих средств и помад. При использовании вместе с интенсивными активами в области вокруг губ рекомендуется соблюдать интервал, чтобы обеспечить комфорт и предотвратить ощущение избыточного слоя. С другими нейтральными средствами взаимодействует без особенностей.', 'Не описана. При чрезмерном нанесении возможно образование плотного покрытия или ощущения излишней плотности, исчезающие после впитывания или лёгкого промокания. Никаких системных эффектов при наружном использовании не предполагается.'),
(8, NULL, 'Тамифлю капсулы 75мг', 'Тамифлю капсулы 75 мг — противовирусный препарат для лечения и профилактики гриппа А и В у взрослых и подростков, содержащий активное вещество осельтамивир. Применяется коротким курсом 5 дней при заболевании и до 10 дней для профилактики после контакта с больным.​', 'Тамифлю — противовирусный препарат из группы ингибиторов нейраминидазы, действующий против вирусов гриппа А и В. Осельтамивир блокирует вирусный фермент нейраминидазу, препятствуя выходу вирусных частиц из инфицированных клеток и дальнейшему распространению инфекции в дыхательных путях.​', 'При раннем начале терапии Тамифлю сокращает длительность симптомов гриппа примерно на один день и снижает риск некоторых осложнений, таких как бронхит, пневмония и отит, особенно у пациентов из групп риска. Препарат не заменяет вакцинацию против гриппа, но может использоваться как дополнение к ней в сезонной эпидемии или при контакте с больным человеком. Наиболее частыми побочными эффектами являются тошнота и рвота, обычно лёгкой или умеренной степени тяжести и проходящие самостоятельно на фоне продолжения лечения.​', 941.00, 'ООО \"НУТРИЛЕНТ\"', NULL, NULL, 0, 'Обычно назначают по 75 мг (1 капсула) 2 раза в день в течение 5 дней для лечения гриппа у взрослых и подростков. Для профилактики рекомендуют по 75 мг 1 раз в день в течение как минимум 10 дней после контакта и до 6 недель при сезонной вспышке. Капсулу принимают внутрь, запивая водой, независимо от приёма пищи, но приём с едой может снизить риск тошноты.​', 54, 'https://cdn.stolichki.ru/s/drugs/medium/10/10786.jpg', NULL, '2025-12-18 19:29:08', '', 'Тамифлю показан для лечения острого, неосложнённого гриппа А и В у пациентов старше 13 лет, если симптомы начались не более 48 часов назад. Также используется для профилактики гриппа у взрослых и подростков в период сезонных вспышек и после тесного контакта с инфицированным лицом.​', 'Одна капсула Тамифлю 75 мг содержит 75 мг осельтамивира фосфата, что соответствует 75 мг осельтамивира в пересчёте на свободное основание. Вспомогательные вещества капсулы включают лактозу, крахмал, повидон, кроскармеллозу натрия, тальк и красители, входящие в состав желатиновой оболочки.​', 'Препарат противопоказан при повышенной чувствительности к осельтамивиру или любому компоненту капсул. Не рекомендуется при тяжёлой почечной недостаточности без диализа и некоторым редким наследственным нарушениях метаболизма, связанным с непереносимостью сахаров (например, дефицит лактазы).​', 'Осельтамивир обычно мало взаимодействует с другими лекарствами, так как слабо метаболизируется системой цитохрома P450 и не влияет на основные изоферменты. Тем не менее при комбинированной терапии с препаратами, влияющими на функцию почек или конкурирующими за канальцевую секрецию, требуется осторожность и контроль состояния пациента.​', 'При передозировке возможны усиление типичных побочных реакций (тошнота, рвота, головокружение) и выраженные симптомы со стороны желудочно‑кишечного тракта. Рекомендуется поддерживающая терапия, контроль жизненно важных функций и симптоматическое лечение, специфического антидота нет.'),
(9, NULL, 'Тройная Омега‑3 950 мг', 'Тройная Омега‑3 950 мг — высококонцентрированные капсулы рыбьего жира с содержанием 950 мг омега‑3 (ЭПК и ДГК) в каждой капсуле для поддержки сердца, сосудов, мозга и суставов. Рекомендуется взрослым как дополнительный источник полиненасыщенных жирных кислот омега‑3 для ежедневного приёма.', 'Тройная Омега‑3 950 мг — концентрированный источник морских полиненасыщенных жирных кислот, созданный для тех, кто хочет получить «тройную» дозу омега‑3 в одной капсуле. Высокая степень очистки рыбьего жира и использование сырья фарм‑качества помогают снизить содержание примесей и посторонних запахов. Омега‑3 участвуют в формировании и защите клеточных мембран, поддерживают эластичность сосудистой стенки, влияют на липидный профиль крови и работу нервной системы.', 'Регулярный приём Тройной Омега‑3 950 мг способствует снижению уровня «плохого» холестерина и триглицеридов, поддерживает нормальное состояние сосудов и микроциркуляции, что важно при повышенных кардиометаболических рисках и малоподвижном образе жизни. Высокое содержание ЭПК и ДГК положительно влияет на работу мозга: улучшает устойчивость к умственным нагрузкам, поддерживает концентрацию внимания, скорость реакции и память, особенно у студентов, офисных работников и людей старшего возраста. За счёт участия омега‑3 в регенерации и защите хрящевой ткани и синовиальной жидкости БАД помогает уменьшить жёсткость суставов и поддерживать их подвижность при физических нагрузках и занятиях спортом. Дополнительно омега‑3 улучшают состояние кожи (упругость, гладкость), снижают сухость, укрепляют волосы и ногти, что делает препарат частью Anti‑Age‑подхода к уходу за собой. Использование очищенного рыбьего жира и антиоксидантов (токоферолов) снижает риск прогоркания и появления характерного рыбного запаха, повышая комфорт регулярного приёма.', 1190.00, 'ООО \"НУТРИЛЕНТ\"', 2, NULL, 0, 'Взрослым: по 1 капсуле 1 раз в день во время еды, запивая достаточным количеством воды. Курс приёма обычно составляет 1 месяц; при необходимости курсы можно повторять несколько раз в год. Капсулу глотают целиком, не разжёвывая, желательно принимать в одно и то же время суток для более стабильного эффекта. Не является лекарством; перед длительным применением рекомендуется консультация врача, особенно при наличии хронических заболеваний или приёме лекарственных препаратов, влияющих на свёртываемость крови.', 44, '/AptekaWebSite/uploads/1777371620_5uwezceyd1umckzl9ns0we60hf38i5f4.png', NULL, '2025-12-18 19:56:28', 'bad', 'Дополнительный источник омега‑3 ПНЖК при несбалансированном питании и низком потреблении морской рыбы.\r\nПоддержка здоровья сердца и сердечно‑сосудистой системы, в т.ч. при повышенном уровне холестерина и триглицеридов.\r\nПоддержка когнитивных функций: памяти, внимания, способности к обучению, особенно при умственных нагрузках и в старшем возрасте.\r\nПоддержание здоровья суставов, связок и хрящей, улучшение эластичности тканей.\r\nУкрепление иммунитета и общего тонуса организма.\r\nПоддержка здоровья кожи, волос и ногтей, Anti‑Age‑эффект за счёт нормализации липидного обмена и защиты клеточных мембран.', '1 капсула (масса содержимого около 1300 мг) содержит:\r\n\r\nРыбий жир из морской рыбы (сардины, хамса, скумбрия) — 1300 мг.\r\nПолиненасыщенные жирные кислоты омега‑3 — 950 мг.\r\nВ том числе эйкозапентаеновая кислота (ЭПК) — порядка 550 мг.\r\nДокозагексаеновая кислота (ДГК) — порядка 230 мг.\r\nВспомогательные компоненты капсулы: желатин (оболочка), глицерин (увлажнитель), смесь натуральных токоферолов (антиоксидант для защиты от окисления жира).', 'Индивидуальная непереносимость компонентов (рыбий жир, продукты морской рыбы, желатин и др.).\r\nБеременность и период грудного вскармливания — только после консультации с врачом.\r\nДетский возраст (до 18 лет) — по согласованию с врачом/педиатром.\r\nС осторожностью применять при нарушениях свёртываемости крови, приёмe антикоагулянтов, тяжёлых нарушениях функции печени и желчевыводящих путей.', 'Может потенцировать эффект антикоагулянтов (варфарин и др.) и антиагрегантов, поэтому при их совместном применении требуется контроль показателей свёртываемости и консультация врача.\r\nСовместим с большинством витаминов и минералов, комплексами для сердца, суставов и иммунитета; обычно входит в состав комбинированных схем.\r\nНе рекомендуется одновременный бесконтрольный приём с другими высокодозированными источниками омега‑3, чтобы избежать избыточной нагрузки жирными кислотами.', 'При значительном превышении рекомендованной дозы возможны:\r\nдиспептические явления (тошнота, жидкий стул, неприятный привкус рыбы, изжога);\r\n\r\nусиление склонности к кровоточивости при наличии нарушений свёртывания или приёме антикоагулянтов;\r\nдискомфорт в области живота, ощущение тяжести.\r\nПри подозрении на передозировку приём капсул прекращают, проводят симптоматическую терапию, при необходимости обращаются к врачу.'),
(10, NULL, 'Тирозин 500 мг/ L-Tyrosine 500 mg', 'L‑тирозин – это условно незаменимая аминокислота, которая участвует в синтезе нейромедиаторов (дофамин, норадреналин, адреналин), гормонов щитовидной железы и пигмента меланина.', 'L‑тирозин – это условно незаменимая аминокислота, которая участвует в синтезе нейромедиаторов (дофамин, норадреналин, адреналин), гормонов щитовидной железы и пигмента меланина.\r\nНа фоне стресса, интенсивной умственной работы, недосыпания и высоких физических нагрузок потребность в тирозине возрастает, а его дополнительный приём может поддерживать когнитивные функции, устойчивость к стрессу и субъективное чувство энергии.\r\nПродукт «Тирозин 500 мг / L‑Tyrosine 500 mg» предназначен для взрослых в качестве дополнительного источника аминокислоты тирозина, не является лекарственным средством и используется в составе комплексных программ по поддержанию нервной системы, работоспособности и настроения.', 'Регулярный приём тирозина в составе БАД может способствовать поддержанию концентрации внимания, скорости реакции и работоспособности в ситуациях, когда нервная система испытывает повышенную нагрузку: сессии, дедлайны, сменная работа, интенсивные тренировки, воздействие холода или шума.\r\n​\r\nБлагодаря участию в синтезе дофамина и норадреналина, L‑тирозин рассматривается как средство, поддерживающее мотивацию, эмоциональную устойчивость и адаптацию к кратковременным стрессовым факторам, что отмечено в ряде исследований на фоне когнитивных и физических нагрузок.\r\nДополнительно тирозин участвует в синтезе тиреоидных гормонов, которые регулируют обмен веществ и общий энергетический уровень, поэтому его дефицит или повышенная потребность могут отражаться на самочувствии, настроении и уровне бодрости.\r\nПри этом добавки тирозина не заменяют полноценного питания, отдыха и назначенной врачом терапии, а должны использоваться как вспомогательный элемент образа жизни после предварительной консультации со специалистом, особенно при наличии хронических заболеваний и приёме лекарственных препаратов.', 879.00, 'ООО \"НУТРИЛЕНТ\"', 2, NULL, 0, 'Взрослым обычно рекомендуют принимать по 1 капсуле (500 мг) 1–2 раза в сутки, за 20–30 минут до еды, запивая достаточным количеством воды, если иное не указано производителем или врачом.\r\nКурс приёма обычно составляет от 30 до 45 дней, при необходимости возможно повторение курса после перерыва по согласованию со специалистом.​\r\nНе рекомендуется принимать тирозин во второй половине дня у людей с повышенной чувствительностью к стимуляторам, чтобы избежать возможного возбуждения и нарушения сна.', 99, '/apteka/uploads/1766179434_1766179167_6945c15f3ad36.png', NULL, '2025-12-19 21:19:27', 'bad', 'Тирозин может рекомендоваться в составе БАД для поддержания когнитивных функций, концентрации внимания и работоспособности в условиях стресса, повышенных умственных и физических нагрузок.\r\n​\r\nИспользуется как вспомогательное средство при снижении настроения, быстрой утомляемости, ощущении «эмоционального выгорания», а также в период интенсивной учёбы, сменной работы или недосыпания.\r\nДополнительно может применяться при снижении аппетита и контроле массы тела в составе комплексных программ, так как участвует в синтезе катехоламинов, влияющих на чувство насыщения и общую активность.\r\n​', 'Одна капсула содержит: L‑тирозин – 500 мг (аминокислота в свободной форме, участвующая в синтезе дофамина, норадреналина, адреналина и тиреоидных гормонов).\r\nВспомогательные вещества (пример): капсула из желатина или растительного полимера, антислёживатели, стабилизаторы или наполнители (в зависимости от производителя).', 'Индивидуальная непереносимость компонентов продукта, детский возраст, беременность и период грудного вскармливания (из‑за недостаточности данных по безопасности).\r\nНе рекомендуется при заболеваниях щитовидной железы (гипертиреоз, болезнь Грейвса), тяжёлых нарушениях функции печени и почек, фенилкетонурии, меланоме и неконтролируемой артериальной гипертензии.\r\nС осторожностью и только после консультации врача – при мигрени, наличии психоневрологических заболеваний, а также при приёме психоактивных препаратов.', 'Тирозин может снижать эффективность леводопы, поэтому не рекомендуется одновременный приём с препаратами леводопы без контроля врача.\r\n​\r\nВозможны взаимодействия с ингибиторами МАО и некоторыми антидепрессантами, что может приводить к избыточному повышению артериального давления и риску побочных реакций.\r\nСледует проявлять осторожность при сочетании с стимуляторами ЦНС (например, амфетаминоподобными веществами, некоторыми жиросжигателями и предтренировочными комплексами), чтобы не усиливать возбуждающее действие и нагрузку на сердечно‑сосудистую систему.\r\n​', 'При приёме доз, существенно превышающих рекомендованные, возможно усиление побочных эффектов: тошнота, изжога, головная боль, повышенная раздражительность, нарушения сна, ощущение сердцебиения.\r\nПредполагается, что очень высокие дозы могут вызывать чрезмерную стимуляцию, повышение артериального давления, усиление тревоги, особенно у чувствительных лиц и при сочетании с другими стимулирующими средствами.\r\nПри подозрении на передозировку рекомендуется прекратить приём и обратиться к врачу, захватив упаковку продукта.'),
(11, NULL, 'ФЕМИВЕЛЛ 1 витамины для беременных', 'Комплекс с активной фолиевой кислотой и легкодоступными нутриентами. Для женщин при планировании и на 1 триместре беременности.', 'ФемиВелл 1 — это научно обоснованный витаминно-минеральный комплекс для женщин на этапе планирования беременности и в первом триместре, когда потребность в фолиевой кислоте возрастает в 4 раза, железе — в 1,8 раза, йоде — в 1,5 раза.\r\nСодержит 22 активных компонента в биодоступных формах: глюконат железа (усвояемость 20-30%), цитрат магния, йодид калия, холекальциферол (D3). Фолиевую кислота в дозировке 800 мкг полностью покрывает потребности для профилактики дефектов нервной трубки.\r\nНе содержит ГМО, искусственных красителей, консервантов. Произведено по стандартам GMP, протестировано на тяжёлые металлы и микотоксины. Подходит для вегетарианцев (желатиновая оболочка без животных белков).\r\n​', 'Планирование беременности — критический период, когда 50% женщин имеют дефицит фолиевой кислоты, 40% — витамина D, 30% — железа, что повышает риски выкидыша, анемии, преждевременных родов и дефектов развития плода. ФемиВелл 1 решает эти проблемы комплексно.\r\n\r\nКлючевые преимущества:\r\n\r\nФолиевая кислота 800 мкг (L-метилфолат, активная форма) — снижает риск спинальной бифиды на 72% (MRC Vitamin Study).\r\nЖелезо 14 мг — профилактика анемии, поддержка плацентации и кроветворения матери.\r\nЙод 150 мкг — нормальное развитие мозга и ЦНС плода (рост IQ на 8-10 баллов).\r\nВитамин D3 10 мкг — минерализация костей плода, снижение гестационного диабета на 25%.\r\nДHA-альтернатива — цинк и магний для синтеза омега-3 в организме.\r\n​\r\nКлинически доказано: через 3 месяца приёма нормализуется 92% показателей микроэлементов у женщин с дефицитом (исследование 2022 г.). Совместим с пренатальными УЗИ и скринингами.', 790.00, 'СМБ Технолоджи С.А.', 2, NULL, 1, 'Взрослым женщинам по 1 таблетке в сутки во время еды, запивая достаточным количеством воды (не разжёвывать). Курс — минимум 3 месяца до зачатия и весь первый триместр беременности.\r\nПри подтверждённом дефиците железа или витамина D врач может рекомендовать дополнительный приём после анализа крови. Не превышать суточную дозу — избыток витамина А (ретинола) в высоких дозах противопоказан на ранних сроках.\r\nДля лучшего усвоения железа сочетать с продуктами, богатыми витамином C (цитрусовые, болгарский перец). Не принимать одновременно с чаем, кофе или молоком (блокируют всасывание железа и кальция)', 9, '/apteka/uploads/1766180148_6945c5348f2ee.png', NULL, '2025-12-19 21:35:48', 'strong', 'ФемиВелл 1 разработан специально для женщин на стадии подготовки к беременности и в первом триместре (до 12 недель), когда закладываются основные органы и системы плода.​\r\nКомплекс содержит оптимальные дозировки 13 витаминов и 9 минералов, включая повышенное количество фолиевой кислоты (800 мкг), которая снижает риск дефектов нервной трубки у плода на 70% согласно мета-анализам Cochrane.\r\nРекомендуется при дефиците железа (профилактика анемии у 30-50% беременных), недостатке витамина D (критично для формирования костной системы малыша), йода (для щитовидной железы и интеллекта), а также при несбалансированном питании, стрессе, проживании в северных регионах или вегетарианской диете.\r\n​', 'Каждый комплекс содержит: витамин C (85 мг — 106% суточной нормы), витамин E (15 мг), витамин B1 (1,4 мг), B2 (1,4 мг), B6 (2 мг), B12 (2,5 мкг), фолиевая кислота (800 мкг — 400% нормы для беременных), витамин D3 (10 мкг), витамин A (770 мкг — бета-каротин, безопасная форма), витамин B5 (6 мг), биотин (30 мкг), никотиновая кислота (18 мг).\r\nМинеральный комплекс: железо (14 мг — глюконат, высокая биодоступность), кальций (150 мг), магний (60 мг), цинк (15 мг), медь (1 мг), марганец (2 мг), йод (150 мкг), селен (30 мкг), хром (25 мкг)', 'Гиперчувствительность к компонентам комплекса, тяжёлая почечная недостаточность, гиперкальциемия, гипервитаминоз A или D, гемохроматоз, талассемия, онкологические заболевания в анамнезе (из‑за железа).\r\nНе применять при беременности после 12 недель — для второго и третьего триместров предназначен ФемиВелл 2 и 3 с изменённым соотношением минералов. Индивидуальная непереносимость моно- или поливалентных аллергенов.\r\nС осторожностью при заболеваниях ЖКТ (язва, гастрит — из‑за железа), гипертиреозе (йод), гемолизе у новорождённых в семейном анамнезе.', 'Железо снижает всасывание тетрациклинов, фторхинолонов, бисфосфонатов, левотироксина — интервал между приёмами не менее 2 часов.\r\nКальций и магний могут уменьшать абсорбцию железа и цинка — не сочетать с кальциевыми добавками. Витамин C усиливает всасывание железа, антациды и молочные продукты — снижают.\r\nЙод взаимодействует с препаратами щитовидной железы (левотироксин) — контроль ТТГ обязателен. Высокие дозы витамина A усиливают токсичность ретинола при одновременном приёме с другими источниками.\r\n​', 'Симптомы избытка железа: тошнота, рвота, диарея с кровью, боли в животе, слабость, бледность кожи (особенно опасно для печени). Витамин A: головная боль, сонливость, сухость кожи, выпадение волос.\r\nПриём доз >10 таблеток за сутки требует немедленной госпитализации: промывание желудка, хелаторы (десферал для железа), симптоматическая терапия. Обратиться к токсикологу, захватив упаковку.\r\nХронический избыток йода может спровоцировать тиреотоксикоз, железа — повреждение печени и поджелудочной.'),
(12, NULL, 'Кальций Магний Цинк', 'Комплексная поддержка костной системы и обмена веществ. Оптимальное сочетание кальция, магния и цинка в одной таблетке. Удобство приема: по 2 таблетки в день. Высокий профиль безопасности (без добавления синтетических консервантов и потенциальных аллергенов).', 'Комплекс способствует поддержанию здорового состояния зубов и костной ткани за счет нормализации минерального обмена. Кальций отвечает за структурную основу костей, магний оптимизирует его усвоение и распределение, а цинк участвует в процессах регенерации соединительной ткани. Сочетание этих минералов повышает их биодоступность и обеспечивает эффективное действие на организм. Форма выпуска: 100 или 250 таблеток.', 'Это продукт из линейки Solgar с кальцием, предназначенный для поддержки костной системы. Производитель (бренд Solgar с 1947 года, «Золотой стандарт») подчеркивает:\r\nПроизводство из лучшего сырья небольшими партиями.\r\nОтказ от искусственных ингредиентов и наполнителей.\r\nСобственное производство на заводе полного цикла с высочайшими стандартами качества (USP-фильтры воды, HEPA-фильтры воздуха).\r\nПродукт рекомендован при высокой физической нагрузке, помогает регулировать мышечное расслабление и восстановление после тренировок.\r\nВ отзывах покупатели отмечают исчезновение судорог, нормализацию сна и стула, улучшение состояния суставов.', 1949.00, '', 3, NULL, 0, 'Взрослым, в том числе беременным и кормящим женщинам, принимать по 2 таблетки в день во время еды.', 420, '/apteka/uploads/1777373207_69f0901759ed3.webp', NULL, '2026-04-28 10:46:47', '', 'Поддержание здорового состояния зубов и костной ткани за счет нормализации минерального обмена. Рекомендован при высокой физической нагрузке: помогает регулировать мышечное расслабление и восстановление после тренировок.', 'Активные вещества (биологически активные) на 1 таблетку:\r\n* Кальций (карбонат кальция, цитрат кальция, глюконат кальция) — 333 мг\r\n* Магний (оксид магния, цитрат магния, глюконат магния) — 133 мг\r\n* Цинк (глюконат цинка) — 5 мг\r\n\r\nКарбонат кальция, оксид магния, микрокристаллическая целлюлоза (носитель), мальтодекстрин (носитель), кроскарамеллоза (носитель), глюконат цинка, лимонная кислота (регулятор кислотности), глюконат магния, гидроксипропилметилцеллюлоза (загуститель), глюконат кальция, магниевая соль стеариновой кислоты (антислеживающий агент), цитрат магния, цитрат кальция, глицерин (загуститель), стеариновая кислота (носитель), гидроксипропилцеллюлоза (стабилизатор), оксид магния, карнаубский воск (глазирователь).', 'Индивидуальная непереносимость компонентов.\r\nПеред применением рекомендуется проконсультироваться с врачом (особенно беременным и кормящим).', '', '');
INSERT INTO `products` (`id`, `category_id`, `name`, `short_description`, `description`, `long_description`, `price`, `supplier`, `brand_id`, `brand`, `prescription`, `usage_info`, `stock`, `image`, `photo`, `created_at`, `label`, `indications`, `composition`, `contraindications`, `drug_interactions`, `overdose`) VALUES
(13, NULL, 'Мультивитаминный и минеральный комплекс для мужчин', 'Сбалансированный мультивитаминный и минеральный комплекс премиум-класса, разработанный специально для мужчин. Формула сочетает высокие дозировки ключевых витаминов, легкоусвояемые хелатные формы минералов и запатентованную фито-смесь (женьшень, экстракт африканской сливы, ягоды серенои и крапива). Продукт направлен на комплексную поддержку мужского организма: повышение энергетического потенциала и работоспособности, укрепление стрессоустойчивости, а также поддержание нормальной функции репродуктивной системы и гормонального фона. Произведен по стандарту GMP на собственном заводе полного цикла в США, не содержит ГМО, глютена и искусственных добавок.', '«Мультивитаминный и минеральный комплекс для мужчин» от Solgar — это премиальная сбалансированная формула, созданная с учетом физиологических потребностей активного мужского организма. Продукт представляет собой комбинацию из более чем 25 ключевых нутриентов, усиленную запатентованным растительным комплексом для поддержки мужской силы, выносливости и гормонального фона. В удобной форме таблеток заключены высокоусвояемые хелатные формы минералов и натуральные экстракты. Производится строго по мировым фармацевтическим стандартам GMP без использования глютена, ГМО и искусственных красителей, что гарантирует Золотой стандарт качества с 1947 года.', 'Для поддержания здоровья, работоспособности и активного долголетия мужской организм требует регулярного поступления широкого спектра питательных веществ, которые далеко не всегда удается получить из повседневной пищи. «Мультивитаминный и минеральный комплекс для мужчин» от легендарного американского бренда Solgar создает надежную нутритивную основу, восполняя возможные дефициты по принципу синергии компонентов.\r\n\r\nФундамент формулы составляет мощный антиоксидантный блок во главе с высокой дозировкой витамина С и цитрусовыми биофлавоноидами. Их действие поддерживают витамин Е, селен и ликопин, защищающие клетки от окислительного стресса, вызванного интенсивной работой и неблагоприятной экологией. Полноценный спектр витаминов группы B (В1, В2, В3, В6, В12, биотин) запускает энергетический обмен, превращая питательные вещества в доступную энергию, что напрямую борется с синдромом хронической усталости. Особую ценность представляет хелатная форма магния и цинка — минералов, незаменимых для здоровья нервной системы и мышечных сокращений, что особенно важно для мужчин, ведущих активный образ жизни или занимающихся спортом.\r\n\r\nИсключительной чертой данного комплекса является мужской фитокомлекс. Экстракт африканской сливы и ягод со пальметто (серенои) традиционно используются для поддержания нормальной функции предстательной железы, в то время как корень корейского и американского женьшеня является природным адаптогеном, повышающим выносливость и общий тонус организма. Ликопин и изофлавоны завершают картину, способствуя поддержанию здоровья сердечно-сосудистой системы и гормонального баланса. Продукт заключен в растительную оболочку Aquapolish, которая облегчает проглатывание и защищает активные компоненты. Это не просто витамины, а высокотехнологичный продукт с безупречной репутацией, созданный для тех, кто требует от жизни максимума и не готов мириться с недостатком жизненных сил.', 4984.00, '', 3, NULL, 0, 'Взрослым мужчинам принимать по 3 таблетки в день. Рекомендуется употреблять во время основного приема пищи в первой половине дня (например, во время завтрака), запивая достаточным количеством воды. Продолжительность стандартного курса приема составляет 2–3 недели. Возможны повторные курсы в течение года.', 232, '/apteka/uploads/1777393341_69f0debde757f.webp', NULL, '2026-04-28 16:22:21', '', 'Профилактика и восполнение дефицита витаминов и минералов при несбалансированном питании.\r\nСнижение общего тонуса, повышенная утомляемость, синдром хронической усталости.\r\nПериоды высоких физических и умственных нагрузок, интенсивные занятия спортом.\r\nПоддержание нормального функционирования репродуктивной системы мужчины.\r\nАдаптация организма к стрессовым ситуациям.\r\nПоддержание гормонального баланса в возрастные периоды.', 'Биологически активные вещества на суточный прием (3 таблетки):\r\nВитамины: A (150 мкг), C (400 мг), D3 (10 мкг), E (10 мг), B1 (3 мг), B2 (3 мг), B3/Ниацин (20 мг), B6 (4 мг), Фолиевая кислота (200 мкг), B12 (3 мкг), Биотин (50 мкг), Пантотеновая кислота (6 мг).\r\nМинералы и микроэлементы: Кальций (400 мг), Йод (150 мкг), Магний (400 мг), Цинк (20 мг), Селен (70 мкг), Медь (1,5 мг), Марганец (2 мг), Хром (200 мкг), Молибден (50 мкг), Калий (99 мг).\r\nСпециализированные компоненты: Холин (100 мг), Инозитол (100 мг), Цитрусовые биофлавоноиды (100 мг).\r\nФитокомплекс для мужчин: Экстракт женьшеня корейского (25 мг), экстракт африканской сливы (25 мг), экстракт женьшеня американского (25 мг), экстракт ягод серенои (со пальметто) (25 мг), экстракт листьев крапивы (25 мг), изофлавоны сои (25 мг), ликопин (1 мг).\r\n\r\nВспомогательные вещества и основа: Микрокристаллическая целлюлоза, цитраты, оксиды и бисглицинаты минералов (магния, кальция, калия), оболочка Aquapolish на основе гидроксипропилметилцеллюлозы с натуральными красителями (соки редиса, черной смородины, яблока, экстракт спирулины), кроскарамеллоза, стеарат магния, диоксид кремния и другие агенты, обеспечивающие стабильность формы.', 'Индивидуальная непереносимость любого из компонентов комплекса.\r\nПовышенная нервная возбудимость, хроническая бессонница.\r\nАртериальная гипертензия (повышенное давление), выраженные нарушения сердечной деятельности.\r\nВыраженный атеросклероз.\r\nЗаболевания щитовидной железы, при которых противопоказан прием препаратов йода (в данном случае необходима обязательная консультация врача-эндокринолога).', 'При одновременном приеме с другими витаминно-минеральными комплексами существует риск превышения рекомендуемой суточной дозы активных компонентов, поэтому сочетать их не рекомендуется. Поскольку комплекс содержит йод, его прием следует согласовывать с врачом при параллельном использовании гормональных препаратов для лечения заболеваний щитовидной железы. Компоненты, входящие в состав, могут влиять на усвоение антибиотиков тетрациклинового ряда и фторхинолонов, поэтому интервал между их приемом должен составлять не менее 2 часов.', 'При значительном превышении рекомендованной дозы возможны симптомы гипервитаминоза, диспепсические расстройства (тошнота, расстройство желудка), нарушения сна, повышенная возбудимость или аллергические реакции. Препарат содержит подсластители (маннит), поэтому при чрезмерном употреблении возможен слабительный эффект. При случайной передозировке необходимо прекратить прием и обратиться к врачу.'),
(14, NULL, 'Коэнзим Q-10 капсулы 100 мг', 'Монопрепарат коэнзима Q-10 в высокой дозировке 100 мг для направленной поддержки клеточной энергетики. Содержит исключительно природный транс-изомер убихинона, идентичный тому, что вырабатывается организмом человека. Для максимального усвоения жирорастворимый коэнзим помещен в масляную основу из натурального масла рисовых отрубей и усилен соевым лецитином. Продукт направлен на борьбу с возрастным снижением энергии, антиоксидантную защиту сердца и сосудов, а также на поддержание нормальной работы миокарда. Достаточно одной капсулы в день.', '«Коэнзим Q-10 капсулы 100 мг» от Solgar — это высокодозированный монопродукт для прицельной антиоксидантной защиты и клеточной энергетики. В отличие от дешевых аналогов, Solgar использует исключительно ферментированный транс-изомер убихинона, биологически идентичный тому, что синтезируется в митохондриях человека. Технологичная формула помещает это жирорастворимое вещество в масло рисовых отрубей, что гарантирует максимальное усвоение без необходимости дополнительного приема Омега-кислот. Это идеальный выбор для профилактики возрастных изменений, поддержания ресурса сердечной мышцы и борьбы с клеточным оксидативным стрессом.', 'Энергия жизни начинается на клеточном уровне, и ключевую роль в этом процессе играет коэнзим Q-10 (убихинон) — витаминоподобное вещество, которое подобно биологической «свече зажигания» запускает синтез АТФ в митохондриях. К сожалению, с возрастом (особенно после 35–40 лет) внутреннее производство этого кофермента неумолимо падает, что ведет к снижению тонуса, замедлению восстановительных процессов и повышению утомляемости. Восполнить этот критический дефицит призван препарат «Коэнзим Q-10 капсулы 100 мг» от американского бренда Solgar, который вот уже более 75 лет олицетворяет «Золотой стандарт» нутрицевтиков.\r\n\r\nГлавное преимущество формулы — ее чистота и технологичность. В производстве используется только природный транс-изомер коэнзима Q-10, полученный путем естественной ферментации, а не химического синтеза. Это гарантирует, что молекула будет распознана организмом как «родная» и использована с максимальной эффективностью. Поскольку убихинон является жирорастворимым соединением, Solgar помещает 100 мг активного вещества в среду из ценного масла рисовых отрубей с добавлением соевого лецитина. Такая комбинация создает естественную мицеллярную форму, которая не требует от организма сложной работы по эмульгированию, а значит, коэнзим всасывается быстро и в полном объеме.\r\n\r\nТаблетированные сухие формы Q-10 часто проходят транзитом через ЖКТ, тогда как масляная капсула Solgar гарантирует стабильную концентрацию вещества в плазме крови. Дозировка 100 мг является клинически обоснованной золотой серединой: она достаточно высока для восполнения возрастного дефицита и поддержки сердца, но при этом безопасна для ежедневного многомесячного приема. Продукт не содержит дрожжей, пшеницы, глютена и молочных продуктов, а значит подходит людям с особыми диетическими ограничениями. Это не просто добавка, а инвестиция в клеточное здоровье, позволяющая сохранять бодрость духа и остроту ума независимо от паспортного возраста.', 4141.00, '', 3, NULL, 0, 'Взрослым принимать по 1 капсуле в день непосредственно во время приема пищи. Капсулу не рекомендуется разжевывать, следует запивать достаточным количеством воды (не менее 150–200 мл). Прием во время еды обязателен, так как жиры, содержащиеся в пище, и масло рисовых отрубей в составе капсулы значительно повышают биодоступность и усвоение жирорастворимого коэнзима Q-10. Курс приема составляет не менее 1 месяца, при необходимости курса можно повторять.', 48, '/apteka/uploads/1777394614_69f0e3b6cd5a1.webp', NULL, '2026-04-28 16:43:34', '', 'Повышенная утомляемость и синдром хронической усталости, связанные с замедлением энергетического обмена в клетках.\r\nВозрастное снижение синтеза собственного коэнзима Q-10 (особенно актуально после 40 лет).\r\nПоддержание нормальной работы и сократительной функции сердечной мышцы (миокарда).\r\nПериод восстановления после перенесенных заболеваний и высоких физических нагрузок.\r\nНеобходимость в мощной антиоксидантной защите клеточных мембран от повреждения свободными радикалами.\r\nКомплексная подготовка организма к стрессовым ситуациям.\r\nПрием статинов (препаратов для снижения холестерина), которые снижают естественный уровень Q-10 в организме.', 'Биологически активные вещества на 1 капсулу (суточный прием):\r\nКоэнзим Q-10 (убихинон, транс-изомер) — 100 мг.\r\nВспомогательные вещества (основа капсулы):\r\nНаполнитель/Растворитель: Масло рисовых отрубей (обеспечивает жировую среду для оптимального усвоения).\r\nОболочка капсулы: Желатин, Глицерин (влагоудерживающий агент E422), Вода.\r\nЭмульгатор: Соевый лецитин (E322) — способствует равномерному распределению активного вещества в масле и повышает его всасывание в кишечнике.\r\nАнтислеживающий агент: Диоксид кремния (E551).\r\nПродукт не содержит ГМО, искусственных красителей, глютена и ароматизаторов.', 'Индивидуальная непереносимость любого из компонентов (в том числе непереносимость соевого лецитина).\r\nБеременность и период грудного вскармливания (в связи с отсутствием достаточных клинических данных о влиянии высоких доз добавки на плод и новорожденного).\r\nДетский возраст (до 18 лет).\r\nПеред применением людям с хроническими сердечно-сосудистыми заболеваниями и тем, кто принимает антикоагулянты, рекомендуется проконсультироваться с врачом.', 'Коэнзим Q-10 структурно схож с витамином К (менахиноном) и теоретически может влиять на вязкость крови. При одновременном приеме с антикоагулянтами (в частности, с Варфарином) требуется строгий врачебный контроль, так как Q-10 может снижать эффективность этих препаратов и требовать коррекции их дозировки. Также прием Коэнзима Q-10 настоятельно рекомендован при долгосрочной терапии статинами, поскольку эти препараты подавляют не только синтез холестерина, но и эндогенную выработку собственного Q-10, приводя к дефициту. Совместим с приемом других витаминов и минералов.', 'Коэнзим Q-10 обладает низкой токсичностью, однако при значительном превышении рекомендуемой суточной дозировки (более 300 мг в сутки) возможны диспепсические расстройства со стороны желудочно-кишечного тракта: снижение аппетита, тошнота, диарея или дискомфорт в области живота. В редких случаях у чувствительных лиц возможны кожные аллергические высыпания и нарушения сна (при приеме во второй половине дня). Специфического антидота нет, при появлении симптомов следует отменить прием и провести симптоматическую терапию.'),
(15, NULL, 'Цитрат магния', 'Монопрепарат магния в одной из самых биодоступных органических форм — цитрате (лимоннокислая соль магния). В отличие от неорганических форм (оксид, сульфат), цитрат магния от Solgar превосходно усваивается организмом даже у людей с пониженной кислотностью желудочного сока, не вызывая дискомфорта в ЖКТ. Две таблетки закрывают половину суточной потребности взрослого человека в этом важнейшем макроэлементе, мягко поддерживая нервную систему, снимая мышечные зажимы и нормализуя сердечный ритм. Подходит как мужчинам, так и женщинам в периоды гормональной перестройки (беременность, ПМС, менопауза).', '«Цитрат магния» от Solgar — это классика нутрицевтической поддержки, эталон чистоты и эффективности органической формы магния. В каждой таблетке содержится чистая лимоннокислая соль, которую не нужно растворять в шипучем стакане, — она уже находится в оптимальной для организма молекулярной связи. Продукт не просто механически восполняет дефицит минерала, а работает на клеточном уровне, мягко запуская парасимпатическую нервную систему (систему «отдыха и восстановления»). Благодаря отсутствию лактозы и глютена, а также удобной форме выпуска, цитрат магния стал бестселлером среди спокойных и осознанных потребителей, выбирающих качество жизни.', 'Магний часто называют «минералом-антистрессом» — и это полностью оправдано, ведь он является кофактором более чем 300 ферментативных реакций, от синтеза белка до регуляции артериального давления. В условиях современного мегаполиса дефицит магния становится тотальной проблемой: стресс буквально «вымывает» его из клеток, создавая порочный круг повышенной тревожности и мышечного гипертонуса. Solgar предлагает решить эту проблему с помощью высококачественного цитрата магния — органической соли, которая по данным клинической фармакологии обладает наивысшей скоростью и полнотой абсорбции.\r\n\r\nВыбор цитратной формы не случаен. В отличие от оксида магния (где элементарного магния много, но он почти не усваивается и действует как жесткое слабительное), цитрат представляет собой «умную молекулу». Лимонная кислота в его составе является естественным участником цикла Кребса — того самого энергетического котла в наших митохондриях. Это значит, что, отдавая ионы магния, она не балластирует организм, а включается в энергообмен. Именно поэтому цитрат магния от Solgar прекрасно подходит людям с чувствительным кишечником и даже тем, кто принимает антациды (снижающие кислотность), так как для его всасывания не требуется высокая кислотность желудочного сока.\r\n\r\nДозировка 200 мг на две таблетки выбрана с умом: она покрывает ту самую «недостающую» половину магния, которую житель мегаполиса недополучает с пищей (зеленью, орехами, бобовыми), но при этом не достигает предела, вызывающего диарею. Это позволяет применять комплекс на постоянной основе без необходимости прерываться на «каникулы». Продукт демонстрирует превосходные результаты как монотерапия при симптомах вегетативной дисфункции: трясущихся ногах при засыпании, синдроме беспокойных ног, внезапных ночных судорогах. Кроме того, это обязательный элемент аптечки каждой женщины в периоды гормональных бурь (ПМС, климакс), когда запасы магния расходуются катастрофически быстро. «Цитрат магния» от Solgar гарантирует спокойствие ума в здоровом теле без побочных эффектов в виде сонливости и заторможенности.', 2188.00, '', 3, NULL, 0, 'Взрослым, в том числе беременным и кормящим женщинам (под наблюдением врача), принимать по 2 таблетки в день во время еды. Таблетки рекомендуется запивать стаканом чистой воды. Прием во время еды минимизирует риск послабляющего действия, которое теоретически возможно при приеме высоких доз магния натощак. Дневную дозу можно разделить на два приема (по 1 таблетке утром и вечером) или принять обе таблетки в вечернее время для достижения более выраженного расслабляющего эффекта при проблемах со сном. Продолжительность приема не ограничена по времени при соблюдении дозировок, рекомендованных врачом.', 121, '/apteka/uploads/1777397338_69f0ee5a1acea.webp', NULL, '2026-04-28 17:28:58', '', 'Повышенная раздражительность, тревожность, снижение устойчивости к эмоциональным нагрузкам.\r\nНарушения сна: трудности с засыпанием, прерывистый ночной сон, ранние пробуждения.\r\nМышечные судороги (особенно икроножных мышц), мышечные спазмы и подергивания (включая тики и тремор век).\r\nПовышенная утомляемость, снижение работоспособности и общий упадок сил.\r\nНарушения моторики кишечника (спастические запоры), обусловленные стрессом и вегетативными нарушениями.\r\nПоддержание нормального артериального давления и стабильного сердечного ритма.\r\nПериоды повышенной потребности в магнии: беременность (наблюдение врача), лактация, интенсивные занятия спортом, менопауза.', 'Биологически активные вещества на суточный прием (2 таблетки):\r\nМагний (в форме цитрата магния) — 200 мг.\r\nВспомогательные вещества (основа таблетки):\r\nНоситель/Загуститель: Гидроксипропилцеллюлоза, гидроксипропилметилцеллюлоза (растительного происхождения, формируют матрицу таблетки).\r\nСтабилизатор: Кроскарамеллоза (обеспечивает быструю распадаемость таблетки после проглатывания).\r\nАнтислеживающие агенты: Жирные кислоты (стеариновая кислота), Диоксид кремния (препятствуют комкованию и обеспечивают сыпучесть порошковой массы при производстве).\r\nВлагоудерживающий агент: Глицерин.\r\nПродукт не содержит сахара, соли, крахмала, дрожжей, пшеницы, глютена, генно-модифицированных организмов (ГМО), искусственных красителей и отдушек.', 'Индивидуальная непереносимость любого из компонентов, входящих в состав.\r\nТяжелая почечная недостаточность (нарушение выделительной функции почек может привести к гипермагниемии).\r\nМиастения гравис (аутоиммунное заболевание).\r\nДетский возраст (до 18 лет) без специального назначения врача.\r\nБеременным и кормящим женщинам, лицам с заболеваниями почек или принимающим сердечно-сосудистые препараты перед применением рекомендуется проконсультироваться с врачом.', 'Магний активно взаимодействует с другими минералами и лекарственными препаратами. При одновременном приеме с кальцием важно соблюдать баланс (оптимальное соотношение Ca:Mg = 2:1), так как избыток одного элемента ухудшает всасывание другого. Цитрат магния может снижать всасывание антибиотиков тетрациклинового ряда и препаратов железа, поэтому интервал между их приемом должен составлять не менее 3 часов. При одновременном приеме с диуретиками (мочегонными средствами) может происходить повышенное выведение магния с мочой или, наоборот, его задержка при использовании калийсберегающих диуретиков, что требует лабораторного контроля.', 'При значительном превышении рекомендованных доз (особенно на фоне почечной недостаточности) возможна гипермагниемия. Ранними симптомами передозировки являются слабительный эффект и дискомфорт в животе, так как непоглощенный магний притягивает воду в просвет кишечника. При дальнейшем злоупотреблении возможны: резкое падение артериального давления, тошнота, рвота, угнетение дыхательного центра и замедление сердечного ритма. Специфическим антидотом при тяжелой гипермагниемии является внутривенное введение препаратов кальция. При развитии диареи на фоне стандартного приема дозу следует временно уменьшить вдвое или отменить прием до нормализации стула.'),
(16, NULL, 'Entresto 100 мг 28 таблеток', 'Инновационный препарат класса АРНИ (ангиотензиновых рецепторов и неприлизина ингибитор) . Содержит уникальную комбинацию двух молекул — сакубитрила и валсартана — в одном кристаллическом комплексе. В отличие от стандартных ингибиторов АПФ, Юперио одновременно блокирует разрушение защитных натрийуретических пептидов и подавляет негативное действие ангиотензина II . Это единственный препарат, доказавший в исследовании PARADIGM-HF превосходство над «золотым стандартом» (эналаприлом) в снижении риска сердечно-сосудистой смерти и госпитализаций .', 'Энтресто 100 мг — это не просто комбинация двух известных веществ, а единое кристаллическое соединение, в котором сакубитрил и валсартан связаны на молекулярном уровне. Такая структура обеспечивает их одновременное поступление в организм в строго выверенной пропорции. Внешне это овальные таблетки, покрытые оболочкой светло-фиолетового оттенка, с гравировкой «NVR» на одной стороне и «L1» на другой. Препарат представляет собой первый и долгое время единственный представитель нового класса АРНИ, принципиально меняющий прогноз при ХСН.', 'В основе действия препарата лежит синергия двух механизмов. Сакубитрил ингибирует фермент неприлизин, который в норме разрушает предсердные натрийуретические пептиды (BNP и ANP). Повышение уровня этих пептидов усиливает выведение натрия и воды (натрийурез и диурез), расширяет сосуды (вазодилатация) и тормозит патологическое ремоделирование миокарда (фиброз). Однако неприлизин также участвует в распаде ангиотензина II, повышение уровня которого крайне опасно. Здесь вступает в действие второй компонент — Валсартан, который избирательно блокирует АТ1-рецепторы ангиотензина II, полностью нивелируя этот потенциальный вред.\r\n\r\nКлючевое клиническое исследование PARADIGM-HF, включившее более 8 000 пациентов, было остановлено досрочно: преимущество Энтресто над эналаприлом было настолько убедительным, что продолжать прием плацебо стало неэтично. Риск сердечно-сосудистой смерти или госпитализации на фоне приема Энтресто снизился на 20% . Препарат продлевает жизнь в среднем на 1–2 года у пациентов с ХСН по сравнению с традиционной терапией. Среди побочных эффектов наиболее частыми являются гипотония (18%) и гиперкалиемия (12%), что требует регулярного мониторинга давления и электролитов крови. Особое внимание уделяется 36-часовому периоду «отмывки» при переходе с ингибиторов АПФ — это правило критической безопасности для предотвращения жизнеугрожающего ангионевротического отека.', 4892.00, '', 4, NULL, 0, 'Способ приема: Внутрь. Таблетку проглатывают целиком, запивая водой, независимо от приема пищи. Кратность приема — 2 раза в сутки.\r\nРежим дозирования при ХСН:\r\nСтартовая доза: 50 мг 2 раза в сутки (или 25 мг при риске гипотонии).\r\nТитрация: Удвоение дозы каждые 2–4 недели при хорошей переносимости.\r\nЦелевая поддерживающая доза: 200 мг (1 таблетка 200 мг) 2 раза в сутки.\r\nВажное условие: Перерыв между отменой ингибиторов АПФ и началом приема Энтресто должен составлять строго 36 часов во избежание риска отека Квинке .', 31, '/apteka/uploads/1777461804_69f1ea2c51349.webp', NULL, '2026-04-29 11:23:24', 'strong', 'Хроническая сердечная недостаточность (ХСН): Лечение пациентов с симптомами (II–IV функциональный класс по NYHA) и сниженной фракцией выброса левого желудочка.\r\nКлючевая цель терапии: Снижение риска сердечно-сосудистой смертности и уменьшение частоты госпитализаций по причине декомпенсации сердечной недостаточности.\r\nПрименение у детей: Терапия симптоматической хронической сердечной недостаточности с систолической дисфункцией левого желудочка у пациентов в возрасте от 1 года.\r\nАртериальная гипертензия: Лечение эссенциальной гипертензии у взрослых (однако в РФ регистрация преимущественно по сердечной недостаточности).', 'Действующие вещества (на 1 таблетку 100 мг):\r\nСакубитрил / Валсартан в форме натриевого солевого комплекса — 100 мг (соответствует 48.6 мг сакубитрила и 51.4 мг валсартана) .\r\nВспомогательные компоненты ядра:\r\nЦеллюлоза микрокристаллическая, гидроксипропилцеллюлоза, кросповидон, магния стеарат, тальк, кремния диоксид коллоидный безводный.\r\nОболочка капсулы:\r\nГипромеллоза, титана диоксид (краситель Е171), макрогол, красители железа оксид (красный и желтый).', 'Гиперчувствительность к сакубитрилу, валсартану или компонентам таблетки.\r\nАнгионевротический отек в анамнезе на фоне приема ингибиторов АПФ или БРА.\r\nНаследственный или идиопатический ангионевротический отек.\r\nОдновременное применение с ингибиторами АПФ (перерыв менее 36 часов между приемом ИАПФ и Энтресто) .\r\nОдновременное применение с алискиреном у пациентов с сахарным диабетом.\r\nБеременность (категория риска для плода) и период грудного вскармливания.\r\nДетский возраст до 1 года (безопасность не установлена).\r\nТяжелые нарушения функции печени (класс С по Чайлд-Пью)', 'Противопоказанные комбинации: Ингибиторы АПФ (риск ангиоотека), Алискирен при диабете.\r\nНерекомендованные комбинации: Блокаторы ангиотензиновых рецепторов (БРА) из-за дублирования механизма.\r\nТребующие осторожности:\r\nКалийсберегающие диуретики (спиронолактон) и препараты калия: риск гиперкалиемии .\r\nНПВС (ибупрофен, диклофенак): ослабление антигипертензивного эффекта и риск ухудшения функции почек.\r\nПрепараты лития: увеличение токсичности.', 'Наиболее вероятным симптомом передозировки является выраженная гипотензия (вплоть до коллапса) вследствие мощного сосудорасширяющего действия.\r\nСимптомы: головокружение, слабость, «туман» перед глазами, обморок.\r\nЛечение: Симптоматическое. Пациента следует уложить, приподнять ноги. Может потребоваться внутривенное введение 0.9% раствора хлорида натрия (физраствора) для восполнения ОЦК. Гемодиализ малоэффективен из-за высокой степени связывания валсартана с белками плазмы .');

